package com.codegym.controller;
import com.codegym.dao.UserDAO; import com.codegym.model.User; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; import java.sql.SQLException;
@WebServlet(name="UserServlet",urlPatterns="/users") public class UserServlet extends HttpServlet {private final UserDAO dao=new UserDAO(); private void forward(HttpServletRequest r,HttpServletResponse s,String p)throws ServletException,IOException{r.getRequestDispatcher(p).forward(r,s);} protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String a=r.getParameter("action"); if(a==null||a.isBlank()||"search".equals(a)){r.setAttribute("users",dao.selectUsers(r.getParameter("country"),r.getParameter("sort")));r.setAttribute("country",r.getParameter("country"));r.setAttribute("sort",r.getParameter("sort"));forward(r,s,"/user/list.jsp");}else if("create".equals(a))forward(r,s,"/user/create.jsp");else{int id=Integer.parseInt(r.getParameter("id"));User u=dao.findById(id);if(u==null){s.sendError(404);return;}r.setAttribute("user",u);if("edit".equals(a))forward(r,s,"/user/edit.jsp");else if("delete".equals(a)){dao.delete(id);s.sendRedirect(r.getContextPath()+"/users");}else{s.sendError(404);}}}catch(SQLException|NumberFormatException e){throw new ServletException(e);}} protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");try{String a=r.getParameter("action");User u=new User(0,r.getParameter("name"),r.getParameter("email"),r.getParameter("country"));if("create".equals(a))dao.insert(u);else if("edit".equals(a)){u.setId(Integer.parseInt(r.getParameter("id")));dao.update(u);}else{ s.sendError(400);return;}s.sendRedirect(r.getContextPath()+"/users");}catch(SQLException|NumberFormatException e){throw new ServletException(e);}}}
